 s=json.loads((ROOT/'sources.json').read_text());b=json.loads((ROOT/'batches.json').read_text())
 decision={'status':'accepted','reviewer':'Codex visual inspection','reviewed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewed_frames':sorted(s['sources']),'reviewed_batches':list(b),'coverage':'All 120 unique poses inspected in 26 native/final edge contacts and 26 three-palette/mask-overlay contacts. Fifteen exact aliases reuse their canonical pixels. All 135 files are native referenced poses.','animation':'Reviewed native/restored standing, attack, hit, death and corpse transition contacts and all direction/action batch sequences. Browser checks cover 192 tracks and 1056 native timing boundaries. Three actor captures include palette B mirrored hit view 7 and palette C death.','appearance':'Dark green and ochre segmented shell, charcoal horns and tail, gray/olive flippers with pale veins, cream cheek plates and yellow eyes retained. Native asymmetric illumination and plain dark underside retained.','corrections':['Identity v1 enlarged and simplified; v2 flat material; accepted v3 uses focused material reference with native multi-view pose authority.','Death views 1/2/3 v1 applied shell decoration to plain belly; corrected v2 retains native plain underside.','Fixed alpha-normalized coarse native illumination guide lowers demonstrated lifted shadows and excessive warm veins across every pose without changing alpha or geometry.','Three enhanced-art coverage masks derive native 581/582/583 palettes deterministically. Neutral gray changes limited to 4 RGB8 levels, preventing matrix extrapolation tint.','Offline viewer uses RGB companions to avoid Canvas premultiplication rounding before recoloring; all 405 variants match baked previews exactly.'],'edge_review':'All final atlas worst-edge light/dark crops inspected. Thin horns, mouth teeth, tail and flipper tips survive; no visible matte rim. Per-frame cleaned and atlas audits pass.','limitations':['New fine texture is an interpretation of low-resolution native art. Source timings, silhouette motion, logical dimensions and native aliases remain authoritative.','Atlas files are staged for future runtime integration; no native artwork or gameplay installation is changed.'],'blockers':[]}
 save(ROOT/'review/decision.json',decision)
 attempts=json.loads((ROOT/'checkpoints/generation_attempts.json').read_text());attempts['status']='accepted';attempts['rejected'][0]['reason']='Enlarged silhouettes, simplified material and bright flippers; superseded by accepted identity v3.'
 for v,reason in [(1,'Shell gold decoration wrongly applied to the plain belly.'),(2,'Corpse underside contained invented gold flecks.'),(3,'Brown shell blocks wrongly applied to the plain belly.')]:
  attempts['rejected'].append({'raw':f'raw/native_d_v{v}_v1.png','prompt':f'prompts/native_d_v{v}_v1.txt','reason':reason,'accepted_replacement':f'raw/native_d_v{v}_v2.png'})
 attempts['selected_batches']={k:json.loads((ROOT/'generation.json').read_text())['batches'][k]['raw']['path'] for k in b};save(ROOT/'checkpoints/generation_attempts.json',attempts)
 lighting=json.loads((ROOT/'lighting_settings.json').read_text());lighting['status']='accepted after all-pose final visual review';save(ROOT/'lighting_settings.json',lighting)
